patterns.template:
श्रेणी {class_name} {
    स्थिर _संस्था = अपरिभाषित
    कर्म getInstance() {
        यदि (_संस्था == अपरिभाषित) {
            _संस्था = नया {class_name}()
        }
        लौटाओ _संस्था
    }
}

श्रेणी {subject_class} {
    संग्रह observers = []
    कर्म subscribe(observer) {
        observers.जोडें(observer)
    }
    कर्म notify(data) {
        के_लिए obs में observers {
            obs.update(data)
        }
    }
}

श्रेणी {context_class} {
    परिवर्तनी strategy = अपरिभाषित
    कर्म setStrategy(strategy) {
        this.strategy = strategy
    }
    कर्म execute(data) {
        लौटाओ strategy.execute(data)
    }
}

कर्म {decorator_name}(func) {
    कर्म wrapper(*args, **kwargs) {
        # Before
        result = func(*args, **kwargs)
        # After
        लौटाओ result
    }
    लौटाओ wrapper
}

श्रेणी {adapter_class} {
    परिवर्तनी adaptee = अपरिभाषित
    कर्म __init__(adaptee) {
        this.adaptee = adaptee
    }
    कर्म request() {
        लौटाओ adaptee.specificRequest()
    }
}

श्रेणी {builder_class} {
    परिवर्तनी product = अपरिभाषित
    कर्म step1() {
        # configure part 1
        लौटाओ self
    }
    कर्म step2() {
        # configure part 2
        लौटाओ self
    }
    कर्म build() {
        लौटाओ product
    }
}

श्रेणी {command_class} {
    कर्म execute() {
        # perform action
    }
    कर्म undo() {
        # reverse action
    }
}

श्रेणी {iterator_class} {
    कर्म __iter__() {
        लौटाओ self
    }
    कर्म __next__() {
        # return next element or raise StopIteration
    }
}

श्रेणी {proxy_class} {
    परिवर्तनी real_subject = अपरिभाषित
    कर्म request() {
        यदि (real_subject == अपरिभाषित) {
            real_subject = RealSubject()
        }
        लौटाओ real_subject.request()
    }
}
